#include "mesh.h"#include "FileStuff.h"#include "BMP.h"OSErr putWaterMask ( FSSpec theMeshFSSpec );OSErr putWaterMask ( FSSpec theMeshFSSpec ){//----------------------------------vars--------------------------------------------------	short		theMeshFileRef;	OSErr		theError;	int i, k;	int x, y;	int waterFound;	int thePadLength;		char	*theGrid, *theTypes, *theItems, *theActions, *theUnknown;	long	gridOffset, typesOffset, itemsOffset, actionsOffset, waterMaskOffset, unknownOffset;	long	theNewMaskLength;	char *theMask;	unsigned short *theMaskData;	long theWidth, theHeight, theSize;	meshHeader theMeshHeader;//----------------------------------------------------------------------------------------			theError = FSpOpenDF ( &theMeshFSSpec, fsRdWrPerm, &theMeshFileRef );	if ( theError != noErr )		return theError;	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	theWidth = theMeshHeader.meshWidth * 256;	theHeight = theMeshHeader.meshHeight * 256;	theSize = theWidth * theHeight;	gridOffset = 1088;	typesOffset = theMeshHeader.itemTypeOffset + 1088;	itemsOffset = theMeshHeader.itemOffset + 1088;	actionsOffset = theMeshHeader.actionOffset + 1088;	waterMaskOffset = theMeshHeader.waterMaskOffset + 1088;	unknownOffset = theMeshHeader.unknown3_Offset + 1088;	theGrid = (char *) NewPtr ( theMeshHeader.meshLength );	if ( theGrid == nil ){		FSClose ( theMeshFileRef );		return -1;	}	theTypes = (char *) NewPtr ( theMeshHeader.itemTypeLength );	if ( theTypes == nil ){		DisposePtr ( theGrid );		FSClose ( theMeshFileRef );		return -1;	}	theItems = (char *) NewPtr ( theMeshHeader.itemLength );	if ( theItems == nil ){		DisposePtr ( theTypes );		DisposePtr ( theGrid );		FSClose ( theMeshFileRef );		return -1;	}	theActions = (char *) NewPtr ( theMeshHeader.actionLength );	if ( theActions == nil ){		DisposePtr ( theItems );		DisposePtr ( theTypes );		DisposePtr ( theGrid );		FSClose ( theMeshFileRef );		return -1;	}	theUnknown = (char *) NewPtr ( theMeshHeader.unknown3_Length );	if ( theUnknown == nil ){		DisposePtr ( theActions );		DisposePtr ( theItems );		DisposePtr ( theTypes );		DisposePtr ( theGrid );		FSClose ( theMeshFileRef );		return -1;	}	FileSeek ( theMeshFileRef, gridOffset );	FileRead ( theGrid,  theMeshHeader.meshLength, theMeshFileRef );	FileSeek ( theMeshFileRef, typesOffset );	FileRead ( theTypes,  theMeshHeader.itemTypeLength, theMeshFileRef );	FileSeek ( theMeshFileRef, itemsOffset );	FileRead ( theItems,  theMeshHeader.itemLength, theMeshFileRef );	FileSeek ( theMeshFileRef, actionsOffset );	FileRead ( theActions,  theMeshHeader.actionLength, theMeshFileRef );	FileSeek ( theMeshFileRef, unknownOffset );	FileRead ( theUnknown,  theMeshHeader.unknown3_Length, theMeshFileRef );		theMask = (char *) NewPtr ( theSize );	if ( theMask == nil ){		DisposePtr ( theUnknown );		DisposePtr ( theActions );		DisposePtr ( theItems );		DisposePtr ( theTypes );		DisposePtr ( theGrid );		FSClose ( theMeshFileRef );		return -1;	}	theMaskData = (unsigned short *) NewPtr ( ((theWidth + 1) * theHeight + 16) * 2L );	if ( theMaskData == nil ){		DisposePtr ( theMask );		DisposePtr ( theUnknown );		DisposePtr ( theActions );		DisposePtr ( theItems );		DisposePtr ( theTypes );		DisposePtr ( theGrid );		FSClose ( theMeshFileRef );		return -1;	}	theError = readBMP ( "\p:Graphics.in:watermask.bmp", theWidth, theHeight, nil, theMask );	if ( theError != noErr ){		DisposePtr ( (Ptr) theMaskData );		DisposePtr ( theMask );		DisposePtr ( theUnknown );		DisposePtr ( theActions );		DisposePtr ( theItems );		DisposePtr ( theTypes );		DisposePtr ( theGrid );		FSClose ( theMeshFileRef );		return theError;	}	k = 0;	for ( y = 0; y < theHeight; y++ ){		waterFound = false;		for ( x = theWidth - 1; x >= 0; x-- ){											// search across			if (  (waterFound == false)  && (theMask[ x + y * theWidth] != 0) ){		// found water start				theMaskData[k++] = (short) ( ( theWidth - 1 ) - x );				waterFound = true;			}			else if (  (waterFound == true)  && (theMask[ x + y * theWidth] == 0) ){	// found water end				theMaskData[k++] = (short) ( ( theWidth - 2 ) - x );				waterFound = false;			}		}		if ( waterFound == true )			theMaskData[k++] = (short) ( theWidth - 1 );		theMaskData[k++] = (short) theWidth;	}	theNewMaskLength = k * 2;	for ( i = 0; i < 16; i++ )		theMaskData[i + k] = theWidth; 	thePadLength = 16 - ( theNewMaskLength % 16);	if ( thePadLength == 16)		thePadLength = 0;		theMeshHeader.waterMaskLength = theNewMaskLength;	theMeshHeader.itemTypeOffset = theMeshHeader.meshLength;	theMeshHeader.itemOffset = theMeshHeader.itemTypeOffset + theMeshHeader.itemTypeLength;	theMeshHeader.actionOffset = theMeshHeader.itemOffset + theMeshHeader.itemLength;	theMeshHeader.waterMaskOffset = theMeshHeader.actionOffset + theMeshHeader.actionLength;	theMeshHeader.unknown3_Offset = theMeshHeader.waterMaskOffset + theMeshHeader.waterMaskLength + thePadLength;	theMeshHeader.tagLength = theMeshHeader.unknown3_Offset + theMeshHeader.unknown3_Length;	theMeshHeader.plugLength = theMeshHeader.tagLength + 1024;	SetEOF ( theMeshFileRef, 0L );	FileWrite ( &theMeshHeader,  1088, theMeshFileRef );	FileWrite ( theGrid,  theMeshHeader.meshLength, theMeshFileRef );	FileWrite ( theTypes,  theMeshHeader.itemTypeLength, theMeshFileRef );	FileWrite ( theItems,  theMeshHeader.itemLength, theMeshFileRef );	FileWrite ( theActions,  theMeshHeader.actionLength, theMeshFileRef );	FileWrite ( theMaskData,theMeshHeader.waterMaskLength + thePadLength, theMeshFileRef );	FileWrite ( theUnknown,  theMeshHeader.unknown3_Length, theMeshFileRef );	DisposePtr ( (Ptr) theMaskData );	DisposePtr ( theMask );	DisposePtr ( theUnknown );	DisposePtr ( theActions );	DisposePtr ( theItems );	DisposePtr ( theTypes );	DisposePtr ( theGrid );	FSClose ( theMeshFileRef );	return	noErr;}